@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-input.nz-quantity-stepper {
    --_nz-quantity-stepper-button: var(--nz-size-control-md);

    gap: 0;
    padding-inline: 0;
    /* the buttons' hover fill stays inside the rounded corners */
    overflow: clip;

    &[data-size='sm'] {
      --_nz-quantity-stepper-button: var(--nz-size-control-sm);
    }

    &[data-size='lg'] {
      --_nz-quantity-stepper-button: var(--nz-size-control-lg);
    }
  }

  .nz-quantity-stepper-control {
    inline-size: var(--nz-quantity-stepper-input-width, 3.5rem);
    font: var(--nz-font-label-m);
    letter-spacing: var(--nz-tracking-label-m);
    text-align: center;
    font-variant-numeric: tabular-nums;
    appearance: textfield;

    /* iOS Safari zooms into a focused field under 16 px: Input's larger line, as on every input */
    @media (pointer: coarse) {
      font: inherit;
      letter-spacing: inherit;
    }

    &::-webkit-inner-spin-button,
    &::-webkit-outer-spin-button {
      margin: 0;
      appearance: none;
    }
  }

  .nz-quantity-stepper-button {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--_nz-quantity-stepper-button);
    block-size: 100%;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--nz-quantity-stepper-button-fg, var(--nz-icon-primary));
    font-size: var(--nz-size-icon-sm);
    cursor: pointer;
    transition: background-color var(--nz-duration-fast) var(--nz-easing-standard);

    @media (hover: hover) {
      &:hover:not(:disabled) {
        background: var(--nz-bg-hover);
      }
    }

    &:active:not(:disabled) {
      background: var(--nz-bg-pressed);
    }

    &:disabled {
      color: var(--nz-text-disabled);
      cursor: not-allowed;
    }
  }

  .nz-quantity-stepper-icon {
    display: inline-flex;
  }

  @media (forced-colors: active) {
    .nz-quantity-stepper-button {
      color: ButtonText;
    }

    .nz-quantity-stepper-button:disabled {
      color: GrayText;
    }
  }
}
